// dotenv is loaded once per process from ~/.config/appsflyer-pp-cli/.env (or
// the path under APPSFLYER_CONFIG_DIR). Process env wins over file values per
// the catalog contract — godotenv.Load is no-clobber, so this ordering is
// inherent to the library; we just need to invoke it before reading env vars.
var dotenvOnce sync.Once

func loadDotenvOnce() {
	dotenvOnce.Do(func() {
		configDir := os.Getenv("APPSFLYER_CONFIG_DIR")
		if configDir == "" {
			home, err := os.UserHomeDir()
			if err != nil {
				return
			}
			configDir = filepath.Join(home, ".config", "appsflyer-pp-cli")
		}
		envFile := filepath.Join(configDir, ".env")
		if _, err := os.Stat(envFile); err != nil {
			return
		}
		_ = godotenv.Load(envFile)
	})
}

